BUNDLE_ID="app.insidejoke"
CLERK_APP_URL="https://dashboard.clerk.com/apps/app_3KoTSNveE9z5A0VV06LPhDJbl6t/instances/ins_3KoTSJqYUT5wYzwoxuu3pL8ZLMd"
CLERK_PK="pk_test_dmFzdC10aWNrLTkzNjYuY2xlcmsuYWNjb3VudHMuZGV2JA"
