API_ENV="apps/api/.env"
WORKER_ENV="apps/worker/.env"
MOBILE_ENV="apps/mobile/.env"
RAILWAY_OK=0
EAS=(eas)

# save FILE KEY VALUE writes one value to one app's .env.
save() { ENV_FILE="$1" write_env "$2" "$3"; }

# ask_in FILE KEY "Prompt" / ask_secret_in: like ask/ask_secret, but offer the
# value already saved in that app's .env.
ask_in()        { ENV_FILE="$1" ask "$2" "$3"; }
ask_secret_in() { ENV_FILE="$1" ask_secret "$2" "$3"; }

# rail SERVICE KEY VALUE sets a variable on a Railway service without
# redeploying; the last stage redeploys once.
rail() {
  local service="$1" key="$2" value="$3"
  if (( RAILWAY_OK )) && printf '%s' "$value" \
      | railway variable set "$key" --stdin --service "$service" --environment production --skip-deploys >/dev/null 2>&1; then
    printf '  %s✓ set%s %s on Railway %s\n' "$GREEN" "$RESET" "$key" "$service"
  else
    SKIPPED+=("Railway variable $key on $service")
    warn "couldn't set $key on Railway $service; set it in the Railway dashboard"
  fi
}

# eas_env NAME VALUE stores a public app value in every EAS environment, since
# cloud builds don't see the gitignored apps/mobile/.env.
eas_env() {
  local name="$1" value="$2" env ok=1
  for env in development preview production; do
    (cd apps/mobile && "${EAS[@]}" env:create --name "$name" --value "$value" --environment "$env" \
      --visibility plaintext --scope project --force --non-interactive >/dev/null 2>&1) || ok=0
  done
  if (( ok )); then printf '  %s✓ set%s %s in EAS\n' "$GREEN" "$RESET" "$name"
  else SKIPPED+=("EAS env $name (expo.dev → project → Environment variables)"); warn "couldn't set $name in EAS"; fi
}

run_wizard() {

TOTAL_STAGES=12

if [[ ! -f apps/api/.env.example || ! -f apps/mobile/app.json ]]; then
  printf 'Run this from the root of your inside-joke checkout (git pull first).\n'; exit 1
fi
