    RAILWAY_OK=1; printf '  %s✓ linked%s this folder to the Railway project inside-joke\n' "$GREEN" "$RESET"
  else
    warn "couldn't link to Railway; Railway values will be listed at the end to set by hand"
  fi
fi
command -v eas >/dev/null 2>&1 || EAS=(npx -y eas-cli@latest)
"${EAS[@]}" whoami >/dev/null 2>&1 || "${EAS[@]}" login || true
pause

