ask_in "$API_ENV" R2_ACCESS_KEY_ID "Paste the Access Key ID:"
ask_secret_in "$API_ENV" R2_SECRET_ACCESS_KEY "Paste the Secret Access Key:"
for f in "$API_ENV" "$WORKER_ENV"; do
  save "$f" R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
  save "$f" R2_BUCKET "$R2_BUCKET_NAME"
  save "$f" R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
  save "$f" R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
done
for s in api worker; do
  rail "$s" R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
  rail "$s" R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
  rail "$s" R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"
done
