printf '\n%s' "$DIM"
cat <<'JSON'
    [{ "AllowedOrigins": ["*"], "AllowedMethods": ["PUT", "GET"],
       "AllowedHeaders": ["content-type"], "MaxAgeSeconds": 3600 }]
JSON
printf '%s\n' "$RESET"
