stage "Expo: link the app"
say "Push notifications need an EAS project ID, and cloud builds need the app's public keys."
save "$MOBILE_ENV" EXPO_PUBLIC_API_URL "$API_URL"
save "$MOBILE_ENV" EXPO_PUBLIC_SENTRY_DSN "$SENTRY_DSN_APP"
step "Answer yes when EAS asks to create the project @nadavg/inside-joke."
